comp:
vec3 ret1, neu;
vec2 uv2, uv3;
shader_body
{
float c, s;
uv -= 0.5;
uv *= aspect.xy;    

float dist = 1.0;
float inten = 1.0;
ret1 = vec3(0.0);
float anz = 4.0;
float n = 1.0;
while (n <= anz) {
    c = mod(n, 2.0);
    s = mod((n+1.0), 2.0);
    uv2.x =  uv.x*c - uv.y*s;
    uv2.y =  uv.x*s + uv.y*c;
//    uv2 *= aspect.yx;
    dist = 1.0-fract(1.0/anz*n+q29);
    inten =  sqrt(dist)*(1.0-dist*dist);
    uv3 = fract(2.0*uv2*dist +.5-.0*dist);

    neu = texture(sampler_main, uv3).xyz;

    ret1 = max(ret1,neu*inten);
n++;
}

ret = ret1*3.0;

}
